  const c = new S3Client({ endpoint: process.env.AWS_ENDPOINT_URL, region: 'us-east-1', credentials: { accessKeyId: process.env.AWS_ACCESS_KEY_ID, secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY }, forcePathStyle: true });
  const res = await c.send(new ListObjectsV2Command({ Bucket: 'meteringco-billing-sandbox' }));
  console.log(JSON.stringify(res, null, 2));
  if(res.Contents){
    for(const o of res.Contents){
      console.log('---OBJECT', o.Key);
      const get = await c.send(new GetObjectCommand({ Bucket: 'meteringco-billing-sandbox', Key: o.Key }));
      const body = await get.Body.transformToString();
      console.log(body.slice(0,5000));
    }
  }
})().catch(e=>console.error(e))
