const { CloudWatchClient, GetMetricDataCommand, ListMetricsCommand } = require('@aws-sdk/client-cloudwatch');
(async () => {
  const c = new CloudWatchClient({ endpoint: process.env.AWS_ENDPOINT_URL, region: 'us-east-1', credentials: { accessKeyId: process.env.AWS_ACCESS_KEY_ID, secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY } });
  const res = await c.send(new ListMetricsCommand({ Namespace: 'MeteringCo/Usage' }));
  console.log(JSON.stringify(res, null, 2));
  // also try GetMetricData for known dimensions
  const dims = [
    { BusinessId: 'biz-ridge', CustomerId: 'cus_sample_alpha', DimensionId: 'ridge-api-calls' },
    { BusinessId: 'biz-ridge', CustomerId: 'cus_sample_alpha', DimensionId: 'ridge-seats' },
    { BusinessId: 'biz-ridge', CustomerId: 'cus_sample_alpha', DimensionId: 'ridge-alerts' },
    { BusinessId: 'biz-ridge', CustomerId: 'cus_sample_alpha', DimensionId: 'ridge-reports' },
    { BusinessId: 'biz-ridge', CustomerId: 'cus_sample_alpha', DimensionId: 'ridge-storage' },
    { BusinessId: 'biz-ridge', CustomerId: 'cus_sample_bravo', DimensionId: 'ridge-jobs' },
    { BusinessId: 'biz-ridge', CustomerId: 'cus_sample_bravo', DimensionId: 'ridge-minutes' },
    { BusinessId: 'biz-ridge', CustomerId: 'cus_sample_bravo', DimensionId: 'ridge-scans' },
    { BusinessId: 'biz-ridge', CustomerId: 'cus_sample_bravo', DimensionId: 'ridge-tasks' },
    { BusinessId: 'biz-vale', CustomerId: 'cus_sample_charlie', DimensionId: 'vale-messages' },
    { BusinessId: 'biz-vale', CustomerId: 'cus_sample_charlie', DimensionId: 'vale-hours' },
    { BusinessId: 'biz-vale', CustomerId: 'cus_sample_charlie', DimensionId: 'vale-units' },
  ];
  for(const d of dims){
    const r = await c.send(new GetMetricDataCommand({
      StartTime: new Date('2026-07-01T00:00:00Z'),
      EndTime: new Date('2026-08-01T00:00:00Z'),
      ScanBy: 'TimestampAscending',
      MetricDataQueries: [{ Id: 'series', MetricStat: { Metric: { Namespace: 'MeteringCo/Usage', MetricName: 'AggregatedUsage', Dimensions: Object.entries(d).map(([Name, Value])=>({Name, Value})) }, Period: 3600, Stat: 'Sum' }, ReturnData: true }]
    }));
    console.log(d.DimensionId, JSON.stringify(r.MetricDataResults[0]?.Values), JSON.stringify(r.MetricDataResults[0]?.Timestamps));
  }
})().catch(e=>console.error(e))
